INSERT INTO page_content_items
  (page, section, sort_order, icon, image_path, title, subtitle, description, extra, is_active)
VALUES
  ('about', 'about-hero', 1, NULL, NULL, 'Dream Home Meets Trusted Expertise', NULL, 'At HouseBank, we pride ourselves on being more than just a real estate agency, we are your partners in finding the perfect space to live, work, and thrive.', '{"badge": "Welcome to HouseBank", "paragraph2": "Whether you''re searching for a family home, an investment property, or a commercial space, we are committed to helping you achieve your goals with professionalism and care", "cta_text": "Explore Properties", "cta_link": "/explore"}', 1),
  ('about', 'about-top-features', 1, NULL, NULL, 'Explore', 'Great Neighborhoods', 'We connect with directly to the person that knows the most about property for sale, the listing realtor.', '{"style": "white", "cta_text": "Explore", "cta_link": "/explore"}', 1),
  ('about', 'about-top-features', 2, NULL, NULL, 'Find Highly', 'Rated Best Property', 'We connect with directly to the person that knows the most about property for sale, the listing realtor.', '{"style": "purple", "cta_text": "Explore", "cta_link": "/explore"}', 1),
  ('about', 'about-top-features', 3, NULL, NULL, 'Discover', 'Quality Buildings', 'We connect with directly to the person that knows the most about property for sale, the listing realtor.', '{"style": "white", "cta_text": "Explore", "cta_link": "/explore"}', 1),
  ('about', 'about-who-we-are', 1, NULL, NULL, 'We are Best in Property Management Trusted by 10 Million Buyers', NULL, 'Founded on a passion for connecting people with the right properties, HouseBank Real Estate has grown to become a trusted name in the real estate industry. Our team of experienced realtors combines market insight with personalized service, ensuring you receive the guidance you need at every step of your property journey.', '{"eyebrow": "Who We Are"}', 1),
  ('about', 'about-why-choose-us', 0, NULL, NULL, 'Why Choose Us?', NULL, NULL, '{"kind": "header", "cta_text": "Explore Properties", "cta_link": "/explore"}', 1),
  ('about', 'about-why-choose-us', 1, NULL, NULL, 'Customer-Centric Approach:', NULL, 'Your satisfaction is our priority. We listen, understand, and deliver solutions tailored to your needs.', NULL, 1),
  ('about', 'about-why-choose-us', 2, NULL, NULL, 'Transparency and Integrity:', NULL, 'Honesty and fairness guide everything we do.', NULL, 1),
  ('about', 'about-why-choose-us', 3, NULL, NULL, 'Market Expertise:', NULL, 'With a deep understanding of the real estate market, we provide insights to help you make confident decisions.', NULL, 1),
  ('about', 'about-why-choose-us', 4, NULL, NULL, 'End-to-End Support:', NULL, 'From property search to closing the deal, we are with you every step of the way.', NULL, 1),
  ('about', 'about-bottom-features', 1, 'Star', NULL, 'Our Mission', NULL, 'To connect people with properties that inspire them and meet their needs while ensuring a seamless and rewarding process for all our clients.', '{"additionalText": "At HouseBank Real Estate, we don''t just sell properties—we help you build a foundation for your future. Let''s find your dream home today!"}', 1),
  ('about', 'about-bottom-features', 2, 'Star', NULL, 'Our Vision', NULL, 'To be the trusted leader in real estate, transforming lives by providing exceptional properties and services that inspire dreams, build communities, and create lasting value for generations to come.', NULL, 1),
  ('about', 'about-bottom-features', 3, 'Star', NULL, 'Our Aim', NULL, 'At HouseBank Real Estate, our goal is to make property ownership and investment seamless, trustworthy, and rewarding. We strive to connect individuals and businesses with the perfect spaces while fostering lasting relationships built on transparency, expertise, and care. Your dream property is our mission.', NULL, 1),
  ('about', 'about-team', 0, NULL, NULL, 'Our Team', NULL, 'At House Bank Real Estate, we make renting, buying, and investing in property seamless and rewarding. Whether you''re looking for your next home, rental space, or a lucrative investment opportunity, our team is here to guide you every step of the way.', '{"kind": "header"}', 1),
  ('about', 'about-team', 1, NULL, NULL, 'Oluwafemi Adegbanga', 'Founder & CEO', 'With a vision to revolutionize the real estate industry, Oluwafemi founded HouseBank Real Estate to offer personalized and innovative property solutions, leading the team with integrity, innovation, and a client-first approach.', '{"twitter": "#", "facebook": "#", "linkedin": "#"}', 1),
  ('about', 'about-team', 2, NULL, NULL, 'Oluwafemi Adegbanga', 'Chief Operating Officer', 'As Chief Operating Officer, Oluwafemi oversees day-to-day operations at HouseBank Real Estate, making sure every client interaction reflects our commitment to integrity, innovation, and a client-first approach.', '{"twitter": "#", "facebook": "#", "linkedin": "#"}', 1),
  ('about', 'about-team', 3, NULL, NULL, 'Oluwafemi Adegbanga', 'Senior Sales Manager', 'As Senior Sales Manager, Oluwafemi leads the sales team at HouseBank Real Estate, helping clients navigate the market with expert guidance built on integrity, innovation, and a client-first approach.', '{"twitter": "#", "facebook": "#", "linkedin": "#"}', 1),
  ('about', 'about-team', 4, NULL, NULL, 'Oluwafemi Adegbanga', 'Leasing Consultant', 'As a Leasing Consultant at HouseBank Real Estate, Oluwafemi helps tenants and property owners find the right fit, guided by integrity, innovation, and a client-first approach.', '{"twitter": "#", "facebook": "#", "linkedin": "#"}', 1),
  ('services', 'services-hero', 1, NULL, NULL, 'Your Trusted Partner in Real Estate', NULL, 'At House Bank Real Estate, we are committed to providing you with exceptional real estate solutions tailored to meet your unique needs. Whether you''re buying your dream home, selling a property, or investing in real estate, we''ve got you covered.', '{"badge": "our Service", "cta_text": "Explore our Offer", "stats": [{"number": "20k", "label": "Happy customers"}, {"number": "10k +", "label": "Client reviews"}, {"number": "4.5", "label": "Positive Rating"}]}', 1),
  ('services', 'services-detail', 0, NULL, NULL, 'What We Do For You', NULL, NULL, '{"kind": "header", "eyebrow": "Services we Provide"}', 1),
  ('services', 'services-detail', 1, NULL, 'https://images.unsplash.com/photo-1560472354-b33ff0c44a43?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1926&q=80', 'Property Management', NULL, 'We handle every aspect of managing your property so you can enjoy the benefits without the stress.', '{"layout": "image-left", "bullets": ["Tenant screening, placement, and support.", "Rent collection and income disbursement.", "Maintenance, repairs, and regular property inspections.", "Legal compliance and documentation."], "what_you_get": "Peace of mind knowing your property is in expert hands while maximizing returns."}', 1),
  ('services', 'services-detail', 2, NULL, 'https://images.unsplash.com/photo-1554224155-6726b3ff858f?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=2026&q=80', 'Property Valuation', NULL, 'Understand the true value of your property with our accurate and reliable valuation services.', '{"layout": "content-left", "bullets": ["Market analysis and data-driven insights.", "Expert assessment of residential, commercial, and land properties.", "Comprehensive reports for sales, purchases, or investment decisions."], "what_you_get": "Confidence in making informed real estate decisions backed by expert evaluations."}', 1),
  ('services', 'services-detail', 3, NULL, 'https://images.unsplash.com/photo-1450101499163-c8848c66ca85?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=2070&q=80', 'Property Exchange', NULL, 'Looking to upgrade, downsize, or diversify your portfolio? Our property exchange service makes transitions easy.', '{"layout": "image-left", "bullets": ["Seamless swapping of properties to suit your evolving needs.", "Wide network of listings for residential, commercial, and investment properties.", "Transparent and efficient processes to match you with the perfect exchange."], "what_you_get": "Flexibility to adapt your property portfolio without the hassle of traditional sales."}', 1),
  ('services', 'services-detail', 4, NULL, 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1974&q=80', 'Investment Portfolio', NULL, 'Grow your wealth with tailored real estate investment strategies.', '{"layout": "content-left", "bullets": ["Portfolio analysis and optimization.", "Access to high-yield investment opportunities.", "Expert guidance on market trends and forecasts.", "Strategic advice for diversifying and maximizing returns."], "what_you_get": "A lucrative and secure investment portfolio aligned with your financial goals."}', 1),
