  ('realtor', 'realtor-hero', 1, NULL, NULL, 'Become an Realtor', NULL, 'Effortlessly buy, sell, and invest in real estate with HouseBank. Whether you''re a realtor, developer, or investor, we provide the tools and connections you need to close deals faster and grow your business.', '{"cta_text": "Register Now", "stats": [{"icon": "Users", "number": "20,000+", "label": "Registered Realtors"}, {"icon": "Home", "number": "50k+", "label": "Houses Uploaded"}, {"icon": "₦", "number": "₦15M", "label": "Amount Realtors Paid"}]}', 1),
