  ('realtor', 'realtor-why-join-steps', 1, NULL, NULL, 'Easy sign up', NULL, 'Start with a free consultation to assess your needs. You''ll provide information about your home and what you would like to get out of your battery storage. You''ll work with an experienced design consultant to evaluate the best solution for you.', NULL, 1),
  ('realtor', 'realtor-why-join-steps', 2, NULL, NULL, 'Connect with customers easily', NULL, 'Our platform makes it simple to connect with potential customers in your area. Get matched with qualified leads and build lasting relationships.', NULL, 1),
  ('realtor', 'realtor-why-join-steps', 3, NULL, NULL, 'Maximum your growth with Housebank', NULL, 'Leverage our tools and resources to expand your business. Access market insights, professional development, and growth opportunities.', NULL, 1),
  ('realtor', 'realtor-why-join-steps', 4, NULL, NULL, 'Withdraw your Earnings fast', NULL, 'Get paid quickly and securely. Our streamlined payment system ensures you receive your earnings without delay.', NULL, 1),
  ('realtor', 'realtor-features', 0, NULL, NULL, 'What Makes HouseBank Stand Out', NULL, 'Effortlessly buy, sell, and invest in real estate with HouseBank. Whether you''re a realtor, developer, or investor, we provide the tools and connections you need to close deals faster and grow your business.', '{"kind": "header", "eyebrow": "Our Features", "bottom_cta_title": "Ready to take your real estate business to the next level", "bottom_cta_text": "Start listing"}', 1),
  ('realtor', 'realtor-features', 1, NULL, NULL, 'Seamless Property Listings', NULL, 'Easily upload, manage, and showcase your properties to a wide audience with our intuitive listing platform.', NULL, 1),
  ('realtor', 'realtor-features', 2, NULL, NULL, 'Verified Leads & High-Quality Buyers', NULL, 'Connect with serious buyers and investors, ensuring faster and more secure transactions.', NULL, 1),
  ('realtor', 'realtor-features', 3, NULL, NULL, 'Secure & Transparent Transactions', NULL, 'Conduct business with confidence using our secure payment and verification system.', NULL, 1),
  ('realtor', 'realtor-features', 4, NULL, NULL, 'Dedicated Support & Marketing Tools', NULL, 'Get expert assistance, promotional tools, and marketing strategies to boost your property sales.', NULL, 1),
  ('realtor', 'realtor-features', 5, NULL, NULL, 'AI-Powered Matching', NULL, 'Our smart recommendation system connects you with the right buyers and properties based on preferences and market demand.', NULL, 1),
  ('realtor', 'realtor-features', 6, NULL, NULL, 'Real-Time Market Insights', NULL, 'Stay ahead with in-depth property analytics and trends to make informed decisions.', NULL, 1),
