  ('property-management', 'pm-services', 1, NULL, NULL, 'Tenant Management', NULL, NULL, '{"bullets": ["Tenant Screening: We conduct thorough background checks to find reliable tenants.", "Lease Agreements: Drafting, negotiation, and renewal of lease contracts.", "Tenant Support: Providing 24/7 assistance for tenant queries and concerns."]}', 1),
  ('property-management', 'pm-services', 2, NULL, NULL, 'Rent Collection and Financial Management', NULL, NULL, '{"bullets": ["Automated rent collection with on-time disbursements.", "Regular financial reporting, including income, expenses, and tax documents.", "Handling late payments and implementing penalties where necessary."]}', 1),
  ('property-management', 'pm-services', 3, NULL, NULL, 'Maintenance and Repairs', NULL, NULL, '{"bullets": ["Scheduling routine property inspections.", "Coordinating maintenance and emergency repairs with trusted contractors.", "Preventative measures to preserve the property''s value and reduce costs."]}', 1),
  ('property-management', 'pm-services', 4, NULL, NULL, 'Marketing and Vacancy Minimization', NULL, NULL, '{"bullets": ["Professional property listings with high-quality images and compelling descriptions.", "Advertising across major platforms and social media to attract tenants quickly.", "Streamlined tenant placement process to minimize vacancy periods."]}', 1),
  ('property-management', 'pm-services', 5, NULL, NULL, 'Legal and Regulatory Compliance', NULL, NULL, '{"bullets": ["Ensuring adherence to local laws, safety regulations, and zoning codes.", "Assistance with eviction procedures when necessary.", "Guidance on property insurance and liability requirements."]}', 1),
