  ('home', 'home-property-guide-faq', 1, NULL, NULL, 'What documents do I need to rent a property?', NULL, 'Typically, you''ll need ID proof, income proof, and references. Requirements may vary by landlord. We Typically, you''ll need ID proof, income proof, and references. Requirements may vary by landlord. Typically, you''ll need ID proof, income proof, and references. Requirements may vary by landlord. Typically, you''ll need ID proof, income proof, and references. Requirements may vary by landlord.', NULL, 1),
  ('home', 'home-property-guide-faq', 2, NULL, NULL, 'How do I know if a property is right for me?', NULL, 'Consider location, budget, amenities, and your long-term needs. Our realtors can help you evaluate properties based on your specific requirements.', NULL, 1),
  ('home', 'home-property-guide-faq', 3, NULL, NULL, 'What''s the typical rental process timeline?', NULL, 'From search to move-in usually takes 2-4 weeks, depending on availability and paperwork processing times.', NULL, 1),
  ('home', 'home-property-guide-faq', 4, NULL, NULL, 'Are utilities included in the rent?', NULL, 'This varies by property. Some include basic utilities while others don''t. Always check the lease agreement carefully.', NULL, 1),
  ('home', 'home-property-guide-faq', 5, NULL, NULL, 'How does HouseBank ensure property quality?', NULL, 'We personally vet all listings and maintain strict quality standards. Our team conducts regular property inspections.', NULL, 1),
