-- Migration 015: generic page_content_items table
-- Makes the marketing/landing-page copy (About, Services, Realtor landing,
-- Property Management landing, and the two homepage sections that were still
-- 100% hardcoded) admin-editable from the DB, per Joan's "whole main website
-- in one push" instruction (Sep 2026).
--
-- Seed data below reproduces the exact current hardcoded copy, so running
-- this migration causes ZERO visible change to the site until an admin
-- actively edits something in Site Content > Page Content.

CREATE TABLE IF NOT EXISTS page_content_items (
  id INT AUTO_INCREMENT PRIMARY KEY,
  page VARCHAR(60) NOT NULL,
  section VARCHAR(80) NOT NULL,
  sort_order INT NOT NULL DEFAULT 0,
  icon VARCHAR(60) NULL,
  image_path VARCHAR(500) NULL,
  title VARCHAR(255) NULL,
  subtitle VARCHAR(255) NULL,
  description TEXT NULL,
  extra JSON NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX idx_page_content_page (page),
  INDEX idx_page_content_page_section (page, section, sort_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

